import React from 'react';
import clsx from 'clsx';
import LoadingSpinner from './LoadingSpinner';

const Button = ({
  children,
  variant = 'primary',
  size = 'md',
  loading = false,
  disabled = false,
  className = '',
  icon: Icon,
  iconPosition = 'left',
  ...props
}) => {
  const baseClasses = 'inline-flex items-center justify-center font-medium rounded-lg transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed';

  const variantClasses = {
    primary: 'bg-gold-gradient text-white hover:shadow-glow hover:scale-105 focus:ring-primary-500 shadow-soft',
    secondary: 'bg-green-gradient text-white hover:shadow-glow-green hover:scale-105 focus:ring-secondary-500 shadow-soft',
    success: 'bg-success-600 text-white hover:bg-success-700 hover:scale-105 focus:ring-success-500 shadow-soft',
    warning: 'bg-warning-600 text-white hover:bg-warning-700 hover:scale-105 focus:ring-warning-500 shadow-soft',
    error: 'bg-error-600 text-white hover:bg-error-700 hover:scale-105 focus:ring-error-500 shadow-soft',
    outline: 'border-2 border-primary-500 text-primary-600 hover:bg-primary-500 hover:text-white hover:shadow-glow hover:scale-105 focus:ring-primary-500',
    ghost: 'text-secondary-700 hover:bg-secondary-100 hover:scale-105 focus:ring-primary-500',
  };

  const sizeClasses = {
    xs: 'px-2.5 py-1.5 text-xs',
    sm: 'px-3 py-2 text-sm',
    md: 'px-4 py-2 text-sm',
    lg: 'px-4 py-2 text-base',
    xl: 'px-6 py-3 text-base',
  };

  const isDisabled = disabled || loading;

  return (
    <button
      className={clsx(
        baseClasses,
        variantClasses[variant],
        sizeClasses[size],
        className
      )}
      disabled={isDisabled}
      {...props}
    >
      {loading && (
        <LoadingSpinner 
          size="sm" 
          color={variant === 'outline' || variant === 'ghost' ? 'gray' : 'white'} 
          className="mr-2" 
        />
      )}
      
      {Icon && iconPosition === 'left' && !loading && (
        <Icon className={clsx('w-4 h-4', children ? 'mr-2' : '')} />
      )}
      
      {children}
      
      {Icon && iconPosition === 'right' && !loading && (
        <Icon className={clsx('w-4 h-4', children ? 'ml-2' : '')} />
      )}
    </button>
  );
};

export default Button;
